        // "EntityType|Key" (e.g. "Blog|1") to just the key value.
        // Preserve the old format for backward compatibility.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id")
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>()
            .UseETagConcurrency();

        // Breaking change 3: HasIndex now throws on Cosmos by default.
        // Use ForCosmosIndex() for a Cosmos-compatible index definition,
        // or remove the index entirely if it was a no-op placeholder.
        // Removing since Cosmos manages indexing via its own indexing policy.
    }
}
