using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 — Discriminator property renamed
        // EF Core 9 changed the default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must preserve the old name.
        modelBuilder.Entity<Blog>()
            .HasDiscriminator<string>("Discriminator");

        // BREAKING CHANGE 2 — id format changed
        // EF Core 8 synthesized the JSON `id` as "EntityType|Key" (e.g. "Blog|1").
        // EF Core 9 maps the key property directly to `id`.
        // Preserve the old format with a shadow property + value generator so
        // existing documents with id "Blog|1" are still found.
        modelBuilder.Entity<Blog>()
            .Property<string>("__id")
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // BREAKING CHANGE 3 — HasIndex now throws on Cosmos
        // EF Core 9 no longer silently ignores HasIndex for Cosmos.
        // Removed the old HasIndex(b => b.Name) call; Cosmos manages
        // its own indexing policy at the container level.
    }
}

/// <summary>
/// Generates id values in the legacy EF Core 8 format: "EntityType|KeyValue".
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    public override string Next(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var key = entry.Property("Id").CurrentValue;
        return $"{entityType}|{key}";
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

